#!/usr/bin/env node
// Refuses the em dash (U+2014) in anything the CLI writes into a generated project.
//   node scripts/check-em-dash.mjs [root...]   default root: src
//
// A project generated by this CLI writes the character on no surface, and what the CLI writes is
// what its templates and its generators hold. So a Handlebars template (`.hbs`) is read whole,
// comments included, since every line of it lands in a generated file; a generator's script is
// read for its string and template literals and its JSX text, which is the text it emits. Tests
// and fixtures are left out: a test refusing the character has to spell it, and a fixture is an
// input document, never output.
import { readdirSync, readFileSync } from "node:fs";
import { relative } from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const SKIPPED_DIRECTORIES = new Set(["node_modules", "dist", "coverage", ".turbo", ".git", "__tests__", "__fixtures__"]);
const EM_DASH = String.fromCodePoint(0x2014);

/**
 * The character as written, or spelled as an escape in a script (`\u2014`), a style sheet
 * (`\2014`) or JSX text and markup (`&mdash;`, `&#8212;`, `&#x2014;`).
 */
export function holdsEmDash(text) {
  return text.includes(EM_DASH) || /\\u2014|\\2014|&mdash;|&#8212;|&#x2014;/i.test(text);
}

function isScanned(name) {
  if (/\.test\.[cm]?[jt]sx?$/.test(name) || name.endsWith(".d.ts")) return false;
  return /\.(?:[cm]?[jt]sx?|hbs)$/.test(name);
}

function listSources(directory, found) {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    if (SKIPPED_DIRECTORIES.has(entry.name)) continue;
    const path = `${directory}/${entry.name}`;
    if (entry.isDirectory()) listSources(path, found);
    else if (isScanned(entry.name)) found.push(path);
  }
  return found;
}

function scriptKind(file) {
  if (file.endsWith(".tsx")) return ts.ScriptKind.TSX;
  if (file.endsWith(".jsx")) return ts.ScriptKind.JSX;
  if (/\.[cm]?js$/.test(file)) return ts.ScriptKind.JS;
  return ts.ScriptKind.TS;
}

/** The text one file writes into a generated project, each piece with the line it starts on. */
export function emittedText(file, text) {
  if (file.endsWith(".hbs")) {
    return text.split("\n").map((line, index) => ({ line: index + 1, text: line }));
  }
  const source = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, scriptKind(file));
  const found = [];
  const visit = (node) => {
    if (ts.isStringLiteralLike(node) || ts.isTemplateLiteralToken(node) || ts.isJsxText(node)) {
      found.push({ line: source.getLineAndCharacterOfPosition(node.getStart(source)).line + 1, text: node.getText(source) });
    }
    ts.forEachChild(node, visit);
  };
  visit(source);
  return found;
}

/** Every piece of emitted text under the roots that holds the character. */
export function findEmDashes(roots) {
  const hits = [];
  for (const root of roots) {
    for (const file of listSources(root, [])) {
      for (const piece of emittedText(file, readFileSync(file, "utf-8"))) {
        if (holdsEmDash(piece.text)) hits.push({ file, line: piece.line, text: piece.text });
      }
    }
  }
  return hits;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const roots = args.length > 0 ? args : [fileURLToPath(new URL("../src", import.meta.url))];
  const hits = findEmDashes(roots);
  for (const hit of hits) console.error(`${relative(process.cwd(), hit.file)}:${hit.line}: em dash in emitted text: ${hit.text.slice(0, 100)}`);
  if (hits.length > 0) {
    console.error(`check-em-dash: ${hits.length} piece(s) of emitted text hold U+2014; write a hyphen-minus, a colon or a comma instead`);
    process.exit(1);
  }
  console.log("check-em-dash: no em dash in templates or generator text");
}
